   333  bool PcapNgFileReaderDevice::open()
   334  {
   335          m_NumOfPacketsRead = 0;
   336          m_NumOfPacketsNotParsed = 0;
   337
   338          if (m_LightPcapNg != nullptr)
   339          {
   340                  PCPP_LOG_DEBUG("pcapng descriptor already opened. Nothing to do");
   341                  return true;
   342          }
   343
   344          m_LightPcapNg = light_pcapng_open_read(m_FileName.c_str(), LIGHT_FALSE);
   345          if (m_LightPcapNg == nullptr)
   346          {
   347                  PCPP_LOG_ERROR("Cannot open pcapng reader device for filename '" << m_FileName << "'");
   348                  m_DeviceOpened = false;
   349                  return false;
   350          }
   351
   352          PCPP_LOG_DEBUG("Successfully opened pcapng reader device for filename '" << m_FileName << "'");
   353          m_DeviceOpened = true;
   354          return true;
   355  }
