   357  bool PcapNgFileReaderDevice::getNextPacket(RawPacket& rawPacket, std::string& packetComment)
   358  {
   359          rawPacket.clear();
   360          packetComment = "";
   361
   362          if (m_LightPcapNg == nullptr)
   363          {
   364                  PCPP_LOG_ERROR("Pcapng file device '" << m_FileName << "' not opened");
   365                  return false;
   366          }
   367
   368          light_packet_header pktHeader;
   369          const uint8_t* pktData = nullptr;
   370
   371          if (!light_get_next_packet((light_pcapng_t*)m_LightPcapNg, &pktHeader, &pktData))
   372          {
   373                  PCPP_LOG_DEBUG("Packet could not be read. Probably end-of-file");
   374                  return false;
   375          }
   376
   377          while (!m_BpfWrapper.matchPacketWithFilter(pktData, pktHeader.captured_length, pktHeader.timestamp, pktHeader.data_link))
   378          {
   379                  if (!light_get_next_packet((light_pcapng_t*)m_LightPcapNg, &pktHeader, &pktData))
   380                  {
   381                          PCPP_LOG_DEBUG("Packet could not be read. Probably end-of-file");
   382                          return false;
   383                  }
   384          }
   385
   386          uint8_t* myPacketData = new uint8_t[pktHeader.captured_length];
   387          memcpy(myPacketData, pktData, pktHeader.captured_length);
   388          if (!rawPacket.setRawData(myPacketData, pktHeader.captured_length, pktHeader.timestamp, static_cast<LinkLayerType>(pktHeader.data_link), pktHeader.original_length))
   389          {
   390                  PCPP_LOG_ERROR("Couldn't set data to raw packet");
   391                  return false;
   392          }
   393
   394          if (pktHeader.comment != nullptr && pktHeader.comment_length > 0)
   395                  packetComment = std::string(pktHeader.comment, pktHeader.comment_length);
   396
   397          m_NumOfPacketsRead++;
   398          return true;
   399  }
