   433  std::string PcapNgFileReaderDevice::getOS() const
   434  {
   435          if (m_LightPcapNg == nullptr)
   436          {
   437                  PCPP_LOG_ERROR("Pcapng file device '" << m_FileName << "' not opened");
   438                  return "";
   439          }
   440
   441          light_pcapng_file_info* fileInfo = light_pcang_get_file_info((light_pcapng_t*)m_LightPcapNg);
   442          if (fileInfo == nullptr)
   443                  return "";
   444          char* res = fileInfo->os_desc;
   445          size_t len = fileInfo->os_desc_size;
   446          if (len == 0 || res == nullptr)
   447                  return "";
   448
   449          return std::string(res, len);
   450  }
